use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/trace-one-square175";
const OLD:&str="/home/ubuntu/src/zopro-perf-work/golden-basis175";
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){let r=Path::new(R);let z=Path::new("/home/ubuntu/src/zk-tools/zopro");
 let manifest:Value=serde_json::from_slice(&fs::read(z.join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json")).unwrap()).unwrap();let mut originals=serde_json::Map::new();
 for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){if let Some(t)=p.strip_prefix("crates/zopro-bn254/"){let bytes=fs::read(z.join(p)).unwrap();assert_eq!(hash(&bytes),h.as_str().unwrap());let q=r.join("bn254").join(t);fs::create_dir_all(q.parent().unwrap()).unwrap();assert!(!q.exists());fs::write(q,&bytes).unwrap();originals.insert(t.into(),h.clone());}}assert_eq!(originals.len(),17);
 for(name,dest)in[("Cargo.toml","Cargo.toml"),("Cargo.lock","Cargo.lock"),("perf.rs","perf.rs"),("kernel.rs","parent-kernel.rs"),("src/bin/probe.rs","src/bin/probe.rs")]{fs::copy(Path::new(OLD).join(name),r.join(dest)).unwrap();}
 let parent=fs::read_to_string(r.join("parent-kernel.rs")).unwrap();let start=parent.find("                    macro_rules! cancel {").unwrap();let end=parent[start..].find("                    cancel!(y);").unwrap()+start+"                    cancel!(y);".len();let cancel=&parent[start..end];
 let tail_start=parent.find("            for j in 0..4 {").unwrap();let tail_end=parent[tail_start..].find("\n}\n").unwrap()+tail_start+3;let tail=&parent[tail_start..tail_end];
 let mut code=String::from("// Private trace-one square. X=a²+b²; Y=2ab+b².\nimpl<C:FpConfig,const MIXED:bool>Ifma8<C,MIXED>{\n #[inline(always)] pub fn trace_one_square(a:&Self,b:&Self)->[Self;2]{unsafe{\n let zero=Self::splat(0);let mask=Self::splat(MASK);let p=split(C::P).map(Self::splat);let inv=Self::splat(C::INV&MASK);let mut x=[zero;6];let mut y=[zero;6];\n macro_rules! row{($i:literal)=>{{\n macro_rules! square{($j:literal,$k:literal)=>{{if $j>=$i{\n let al=_mm512_madd52lo_epu64(zero,a.0[$i],a.0[$j]);let ah=_mm512_madd52hi_epu64(zero,a.0[$i],a.0[$j]);\n let bl=_mm512_madd52lo_epu64(zero,b.0[$i],b.0[$j]);let bh=_mm512_madd52hi_epu64(zero,b.0[$i],b.0[$j]);\n let(al,ah,bl,bh)=if $j==$i{(al,ah,bl,bh)}else{(_mm512_slli_epi64::<1>(al),_mm512_slli_epi64::<1>(ah),_mm512_slli_epi64::<1>(bl),_mm512_slli_epi64::<1>(bh))};\n x[$j]=_mm512_add_epi64(x[$j],_mm512_add_epi64(al,bl));x[$k]=_mm512_add_epi64(x[$k],_mm512_add_epi64(ah,bh));\n y[$j]=_mm512_add_epi64(y[$j],bl);y[$k]=_mm512_add_epi64(y[$k],bh);\n }}};}square!(0,1);square!(1,2);square!(2,3);square!(3,4);square!(4,5);\n macro_rules! cross{($j:literal,$k:literal)=>{{let lo=_mm512_madd52lo_epu64(zero,a.0[$j],b.0[$i]);let hi=_mm512_madd52hi_epu64(zero,a.0[$j],b.0[$i]);y[$j]=_mm512_add_epi64(y[$j],_mm512_slli_epi64::<1>(lo));y[$k]=_mm512_add_epi64(y[$k],_mm512_slli_epi64::<1>(hi));}};}cross!(0,1);cross!(1,2);cross!(2,3);cross!(3,4);cross!(4,5);\n");
 code.push_str(cancel);code.push_str("\n}};}row!(0);row!(1);row!(2);row!(3);row!(4);\n");code.push_str(tail);fs::write(r.join("square.rs"),code).unwrap();
 let p=r.join("bn254/src/ifma8.rs");let mut bytes=fs::read(&p).unwrap();let suffix=b"\n#[cfg(golden_basis)] include!(\"../../parent-kernel.rs\");\n#[cfg(golden_basis)] include!(\"../../square.rs\");\n#[cfg(all(test,golden_basis))] include!(\"../../test-square.rs\");\n";bytes.extend(suffix);fs::write(&p,&bytes).unwrap();
 let probe=r.join("src/bin/probe.rs");let code=fs::read_to_string(&probe).unwrap();assert_eq!(code.matches("V::golden_square(&a[0],&a[1])").count(),1);fs::write(probe,code.replace("V::golden_square(&a[0],&a[1])","V::trace_one_square(&a[0],&a[1])")).unwrap();
 fs::write(r.join("source-audit.json"),serde_json::to_vec_pretty(&json!({"original_field_hashes":originals,"original_field_files":17,"suffix":String::from_utf8(suffix.to_vec()).unwrap(),"inherited_parent_kernel_sha256":hash(parent.as_bytes()),"parent_kernel_exact":fs::read(r.join("parent-kernel.rs")).unwrap()==fs::read(Path::new(OLD).join("kernel.rs")).unwrap(),"old_square_changed":false,"new_helper":"trace_one_square","production_changed":false})).unwrap()).unwrap();println!("17 exact field originals copied; inherited golden kernel exact; new direct symmetric square generated");
}
